import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Slack Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/slack.md","filePath":"integrations/channels/slack.md","lastUpdated":1790952322000}'),s={name:"integrations/channels/slack.md"};function l(i,e,r,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="slack-channel-configuration" tabindex="-1">Slack Channel Configuration <a class="header-anchor" href="#slack-channel-configuration" aria-label="Permalink to &quot;Slack Channel Configuration&quot;">​</a></h1><p>Connect your Memoh bot to Slack to receive direct messages, join channels and threads, read attachments, send files, and reply with streaming.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A Slack workspace you can install apps into, and access to the <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">Slack API dashboard</a>.</li><li>A Memoh bot; channels are configured from its <strong>Platforms</strong> tab.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-in-the-slack-console-create-an-app" tabindex="-1">1. In the Slack console, create an app <a class="header-anchor" href="#_1-in-the-slack-console-create-an-app" aria-label="Permalink to &quot;1. In the Slack console, create an app&quot;">​</a></h3><ol><li>Go to the <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">Slack API dashboard</a> and create a new app.</li><li>Choose the workspace where you want to install the bot.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep the app settings page open — steps 2 through 5 all happen there.</p></div><h3 id="_2-in-the-slack-console-enable-socket-mode" tabindex="-1">2. In the Slack console, enable Socket Mode <a class="header-anchor" href="#_2-in-the-slack-console-enable-socket-mode" aria-label="Permalink to &quot;2. In the Slack console, enable Socket Mode&quot;">​</a></h3><p>Memoh&#39;s Slack adapter uses Socket Mode, so you need an app-level token in addition to the bot token.</p><ol><li>In <strong>Basic Information</strong>, enable <strong>Socket Mode</strong>.</li><li>Create an <strong>App-Level Token</strong> with the <code>connections:write</code> scope.</li><li>Copy the generated token. It starts with <code>xapp-</code>.</li></ol><h3 id="_3-in-the-slack-console-add-bot-token-scopes" tabindex="-1">3. In the Slack console, add bot token scopes <a class="header-anchor" href="#_3-in-the-slack-console-add-bot-token-scopes" aria-label="Permalink to &quot;3. In the Slack console, add bot token scopes&quot;">​</a></h3><p>In <strong>OAuth &amp; Permissions</strong>, add the bot token scopes required by the Slack adapter:</p><ul><li><code>app_mentions:read</code> - receive bot mentions in channels</li><li><code>channels:history</code> - read messages in public channels</li><li><code>groups:history</code> - read messages in private channels</li><li><code>im:history</code> - read direct messages</li><li><code>mpim:history</code> - read group direct messages</li><li><code>chat:write</code> - send replies and thread messages</li><li><code>files:read</code> - read uploaded files and images</li><li><code>files:write</code> - upload outbound files</li><li><code>reactions:write</code> - add and remove reactions</li></ul><p>Also add these recommended scopes if you want Slack conversation names and metadata to show up more completely in Memoh:</p><ul><li><code>channels:read</code></li><li><code>groups:read</code></li><li><code>im:read</code></li><li><code>mpim:read</code></li></ul><h3 id="_4-in-the-slack-console-subscribe-to-bot-events" tabindex="-1">4. In the Slack console, subscribe to bot events <a class="header-anchor" href="#_4-in-the-slack-console-subscribe-to-bot-events" aria-label="Permalink to &quot;4. In the Slack console, subscribe to bot events&quot;">​</a></h3><p>In <strong>Event Subscriptions</strong>, enable bot events and add the inbound event types the Slack adapter handles:</p><ul><li><code>app_mention</code></li><li><code>message.channels</code></li><li><code>message.groups</code></li><li><code>message.im</code></li><li><code>message.mpim</code></li></ul><h3 id="_5-in-the-slack-console-install-the-app-to-your-workspace" tabindex="-1">5. In the Slack console, install the app to your workspace <a class="header-anchor" href="#_5-in-the-slack-console-install-the-app-to-your-workspace" aria-label="Permalink to &quot;5. In the Slack console, install the app to your workspace&quot;">​</a></h3><ol><li>In <strong>OAuth &amp; Permissions</strong>, click <strong>Install to Workspace</strong>.</li><li>Review the permission screen and authorize the app.</li><li>Copy the <strong>Bot User OAuth Token</strong>. It starts with <code>xoxb-</code>.</li></ol><h3 id="_6-in-memoh-add-the-slack-channel" tabindex="-1">6. In Memoh, add the Slack channel <a class="header-anchor" href="#_6-in-memoh-add-the-slack-channel" aria-label="Permalink to &quot;6. In Memoh, add the Slack channel&quot;">​</a></h3><ol><li>Open your bot&#39;s detail page and go to the <strong>Platforms</strong> tab.</li><li>Click <strong>Add Channel</strong> and select <strong>Slack</strong>.</li><li>Fill in: <ul><li><strong>Bot Token</strong>: your <code>xoxb-...</code> token</li><li><strong>App-Level Token</strong>: your <code>xapp-...</code> token</li></ul></li><li>Click <strong>Save and Enable</strong>.</li></ol><h3 id="_7-in-slack-add-the-bot-to-conversations" tabindex="-1">7. In Slack, add the bot to conversations <a class="header-anchor" href="#_7-in-slack-add-the-bot-to-conversations" aria-label="Permalink to &quot;7. In Slack, add the bot to conversations&quot;">​</a></h3><p>After the channel is enabled, the Slack app still needs to be present in the conversations where you want it to work:</p><ul><li>Direct messages: open a DM with the app and send a message.</li><li>Public channels: invite the bot to the channel.</li><li>Private channels: invite the bot explicitly after installation.</li></ul><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Bot Token</strong></td><td>The <strong>Bot User OAuth Token</strong> (<code>xoxb-...</code>) copied after installing the app to the workspace.</td></tr><tr><td><strong>App-Level Token</strong></td><td>The Socket Mode token (<code>xapp-...</code>) created with the <code>connections:write</code> scope.</td></tr></tbody></table><p>Both tokens must come from the same Slack app and workspace.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Invite the bot to a channel and @mention it with <code>/help</code>, or send <code>/help</code> in a DM with the app. If the bot replies with its command list, the channel is working.</p><h2 id="group-chats" tabindex="-1">Group chats <a class="header-anchor" href="#group-chats" aria-label="Permalink to &quot;Group chats&quot;">​</a></h2><p>Slack channels are supported. Invite the bot to a public or private channel, then @mention it to talk to it there. Replies can continue in threads — Slack is the only channel with thread support.</p><h2 id="disable-and-rotate-credentials" tabindex="-1">Disable and rotate credentials <a class="header-anchor" href="#disable-and-rotate-credentials" aria-label="Permalink to &quot;Disable and rotate credentials&quot;">​</a></h2><p>You can disable or remove this channel at any time from the bot&#39;s <strong>Platforms</strong> tab. To rotate credentials, update the <strong>Bot Token</strong> and <strong>App-Level Token</strong> fields and save.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ {#faq}&quot;">​</a></h2><h3 id="why-two-tokens" tabindex="-1">Why does Slack need two tokens? <a class="header-anchor" href="#why-two-tokens" aria-label="Permalink to &quot;Why does Slack need two tokens? {#why-two-tokens}&quot;">​</a></h3><p>Memoh&#39;s Slack adapter uses Socket Mode: the <code>xapp-...</code> app-level token is required in addition to the <code>xoxb-...</code> bot token, and both must come from the same Slack app and workspace.</p><h3 id="cannot-read-files" tabindex="-1">The bot can send messages but cannot read uploaded images or files <a class="header-anchor" href="#cannot-read-files" aria-label="Permalink to &quot;The bot can send messages but cannot read uploaded images or files {#cannot-read-files}&quot;">​</a></h3><p>Check that the <code>files:read</code> scope is enabled.</p><h3 id="no-incoming-messages" tabindex="-1">The bot connects but receives no incoming messages <a class="header-anchor" href="#no-incoming-messages" aria-label="Permalink to &quot;The bot connects but receives no incoming messages {#no-incoming-messages}&quot;">​</a></h3><p>Check the bot events in <strong>Event Subscriptions</strong> and the matching <code>history</code> scopes again.</p>',42)])])}const u=a(s,[["render",l]]);export{k as __pageData,u as default};
